        [MenuItem("Truck Sports/Customizer/Bind Missing Tug Appearance Hosts Only")]
        public static void BindMissingTugAppearanceHosts()
        {
            if(EditorApplication.isPlaying||EditorApplication.isCompiling)throw new InvalidOperationException("Stopped compiled Editor required.");var catalog=AssetDatabase.LoadAssetAtPath<SportsTruckAppearanceCatalog>("Assets/TruckSports/Resources/SportsTruckAppearanceCatalog.asset");var source=AssetDatabase.LoadAssetAtPath<GameObject>(FacadeSource);if(catalog==null||!catalog.Validate(out _)||source==null)throw new InvalidOperationException("Existing validated catalog and installed GR3D source required.");var recipes=catalog.bodies.Select(body=>AssetDatabase.LoadAssetAtPath<SportsTruckFragmentRecipe>(SportsTruckFragmentRecipeAuthoring.Folder+"/"+body.id+".asset")).ToArray();for(int i=0;i<recipes.Length;i++)if(recipes[i]==null||!recipes[i].ValidFor(catalog.bodies[i],out _))throw new InvalidOperationException("Existing independently committed private body recipes required.");const string path="Assets/TruckTugOfWar/Scenes/TruckTugOfWar.unity";var scene=SceneManager.GetSceneByPath(path);bool opened=!scene.isLoaded;if(scene.isLoaded&&scene.isDirty)throw new InvalidOperationException("Save existing scene edits first.");if(opened)scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Additive);
            try
            {
                var roots=scene.GetRootGameObjects();var match=roots.SelectMany(root=>root.GetComponentsInChildren<TugMatch>(true)).Single();if(match.trucks.Length!=8||match.fragments.Length!=8||match.headers.Length!=2||match.ropes.Length!=9||match.fire.Length!=8||match.ruts==null||match.ruts.trails.Length!=32||match.trucks.Any(truck=>truck==null)||match.trucks.Distinct().Count()!=8)throw new InvalidOperationException("Original eight fixed tug trucks, two headers, nine ropes, eight fire pools and32 rut trails required.");
                if((match.appearanceHosts?.Length??0)>0||(match.tugAppearanceHosts?.Length??0)>0||match.trucks.Any(truck=>truck.appearanceHost!=null||truck.GetComponent<SportsTruckAppearanceHost>()!=null)||match.fragments.Any(rig=>rig!=null&&(rig.appearanceHost!=null||rig.fragmentPresentation!=null))){Debug.Log("SPORTS_TUG_APPEARANCE_PRESERVED existing custom/partial bindings retained.");return;}
                if(match.replay==null||match.replay.sources.Length!=8||match.replay.ghosts.Length!=8||match.replay.ghosts.Any(ghost=>ghost==null))throw new InvalidOperationException("Original eight truck replay roots required.");var bodies=new Renderer[8][];var tires=new Renderer[8][];var gear=new Transform[8][];var mapped=new Transform[8][];
                for(int i=0;i<8;i++)
                {
                    var truck=match.trucks[i];var rig=match.fragments[i];if(truck.session!=match||truck.slot!=i||truck.transform.localScale!=Vector3.one||truck.visuals==null||truck.visuals.name!="NWH GR3D visual geometry"||truck.visuals.parent!=truck.transform||rig==null||rig.truck!=truck||rig.sourceBody!=null||rig.pieces.Length!=12||match.replay.sources[i]!=truck.transform)throw new InvalidOperationException("Exact clean original EventTruck/12piece/replay ownership required.");CheckVehicle(truck.transform,truck.visuals,truck.wheels);bodies[i]=ArenaOriginalRenderers(truck.visuals,source.transform,FacadeBodyPaths);tires[i]=ArenaOriginalRenderers(truck.visuals,source.transform,FacadeWheelPaths);var binding=truck.GetComponent<SportsWheelMeshBinding>();if(binding==null||binding.truck!=truck||binding.meshes.Length!=4||!new HashSet<Renderer>(WheelRenderers(truck.transform,truck.wheels,binding)).SetEquals(tires[i]))throw new InvalidOperationException("Original actual mesh-bound four wheels required.");mapped[i]=binding.meshes.ToArray();
                    foreach(string role in SportsTruckFragmentRecipe.BodyRoles.Concat(SportsTruckFragmentRecipe.WheelRoles))if(rig.pieces.Count(piece=>piece!=null&&piece.source!=null&&piece.source.name==role)!=1)throw new InvalidOperationException("Exact original twelve body/wheel roles required.");foreach(var wheel in mapped[i])if(rig.pieces.Count(piece=>piece.source==wheel)!=1)throw new InvalidOperationException("Original wheel mesh must match exactly one existing physical piece source.");if(rig.pieces.Any(piece=>piece.body==null||piece.collider==null||piece.renderer==null||piece.source.GetComponent<MeshFilter>()?.sharedMesh!=piece.renderer.GetComponent<MeshFilter>()?.sharedMesh))throw new InvalidOperationException("Original piece geometry/physics references changed.");
                    gear[i]=match.headers.Select(header=>header.transform).Concat(match.ropes.Select(rope=>rope.transform)).Concat(match.ruts.trails.Skip(i*4).Take(4).Select(trail=>trail.transform)).Concat(new[]{match.fire[i].transform}).ToArray();if(gear[i].Any(part=>part==null||part==truck.visuals||part.IsChildOf(truck.visuals)||truck.visuals.IsChildOf(part)))throw new InvalidOperationException("Original tug equipment overlaps clean presentation.");var known=new HashSet<Renderer>(bodies[i].Concat(tires[i]).Concat(rig.pieces.Select(piece=>piece.renderer)));if(truck.GetComponentsInChildren<Renderer>(true).Any(renderer=>!known.Contains(renderer))||truck.visuals.GetComponentsInChildren<Renderer>(true).Length!=33||truck.visuals.GetComponentsInChildren<Collider>(true).Length!=0||truck.visuals.GetComponentsInChildren<Rigidbody>(true).Length!=0)throw new InvalidOperationException("Unknown truck rendering/physics retained for explicit inspection.");
                }
                var hosts=new SportsTruckAppearanceHost[8];for(int i=0;i<8;i++){var truck=match.trucks[i];var rig=match.fragments[i];var host=Create(truck.transform,truck.visuals,truck.wheels,tires[i],catalog);host.participantSlot=i;host.protectedRoots=gear[i];host.modeOwnedSlots=new[]{SportsTruckAppearanceSlots.Dashboard};foreach(var fit in host.compatibleBodies)fit.notice+=" Tug retains its original tow anchors, balanced traction, rope physics and twelve physical wreck pieces.";var fragment=truck.gameObject.AddComponent<SportsTruckFragmentPresentation>();fragment.authoredVersion=1;fragment.host=host;fragment.rig=rig;fragment.recipes=recipes.ToArray();fragment.recipeBodyIds=recipes.Select(recipe=>recipe.bodyId).ToArray();fragment.eventWheelPieceSources=mapped[i];host.fragmentPresentation=fragment;truck.appearanceHost=host;rig.appearanceHost=host;rig.fragmentPresentation=fragment;hosts[i]=host;EditorUtility.SetDirty(host);EditorUtility.SetDirty(fragment);EditorUtility.SetDirty(truck);EditorUtility.SetDirty(rig);}
