                match.tugAppearanceHosts=hosts;match.appearanceFraming=(match.appearanceFraming??Array.Empty<SportsBroadcastFraming>()).Concat(roots.SelectMany(root=>root.GetComponentsInChildren<SportsBroadcastFraming>(true)).Where(framing=>framing.session==match)).Distinct().ToArray();EditorUtility.SetDirty(match);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Debug.Log("SPORTS_TUG_APPEARANCE_ONLY_BOUND eight explicit EventTruck hosts/wheel-piece source mappings; original headers/ropes/ruts/physics/QTE/rules untouched. Gameplay redesign remains deferred; native appearance proof pending.");
            }
            finally{if(opened)EditorSceneManager.CloseScene(scene,true);}
        }
